src/pages/[category]/[slug].astro.utf8Content:
---
import InlineOrderBanner from '../../components/InlineOrderBanner.astro';
import BaseLayout from '../../layouts/BaseLayout.astro';
import MarkdownContent from '../../components/MarkdownContent.astro';
import ProductCards from '../../components/ProductCards.astro';
import InlineText from '../../components/InlineText.astro';
import pages from '../../data/pages.json';
import products from '../../data/products.json';
import {site,groups} from '../../config/site';
import {selectProducts,productHeading,productFamilies} from '../../lib/catalog.mjs';
import {nextSteps,relatedReading} from '../../lib/journey.mjs';
import editorial from '../../data/editorial-assets.json';
import {pageSources,sourceTypeLabels} from '../../lib/sources.mjs';
import {detailIllustration} from '../../lib/visual.mjs';
import {groupsFor,assertRegionalInput} from '../../lib/regional-runtime.mjs';
assertRegionalInput(pages);
export function getStaticPaths(){return (pages as any[]).map(p=>({params:{category:p.category,slug:p.slug},props:{page:p}}));}
const {page}=Astro.props;
const district=groupsFor(pages).find((d:any)=>d.items.some((item:any)=>item.page.pageKey===page.pageKey));
const regionalSocialProduct=page.pageType==='regional-service' ? products.find(p=>p.img===page.ogImage) : null;
if(page.pageType==='regional-service' && !regionalSocialProduct) throw new Error('Regional social image has no verified product binding');
const journey=nextSteps(page,pages);
const related=relatedReading(page,pages);
const productSet=selectProducts(page,products,page.productCardLimit===4||productFamilies(page).length>3?4:3); const hero=productSet[0];
const illustration=detailIllustration(page,editorial);
const sources=pageSources(page);
const category=groups.find(g=>g.cat===page.category);
const snapshotId=page.snapshotId;
const pricePage=journey.find((p:any)=>p.pageType==='price-guide');
const addressPage=journey.find((p:any)=>p.visualIntent==='order_address');
---
<BaseLayout title={page.title} description={page.description} canonicalPath={page.url} orderUrl={hero?.orderUrl || site.orderUrl} socialProduct={regionalSocialProduct || hero || products[0]}>
<article data-snapshot-id={snapshotId} data-page-key={page.pageKey} data-page-type={page.pageType} data-query-class={page.queryClass} data-visual-intent={page.visualIntent} data-asset-slot={page.assetSlot}>
<nav class="breadcrumb" aria-label="현재 위치"><a href="/">{site.region} 꽃배달</a><span>›</span><a href={category?.url || '/'}>{category?.label || '꽃배달'}</a><span>›</span>{district && <><a href={`/regions/#${district.key}`}>{district.name}</a><span>›</span></>}<span>{page.primaryKeyword}</span></nav>
<section class="detail-hero"><div><span class="eyebrow">{site.brand} {site.region}</span><h1>{page.h1}</h1><p>{page.firstAnswer}</p><div class="actions"><a class="btn primary" href={site.phoneHref}>☎ {site.phone}</a><a class="btn dark" href={hero?.orderUrl || site.orderUrl}>상품 확인·주문</a></div><div class="facts"><span>전화 {site.phoneOrderHours}</span><span>온라인 {site.onlineOrderHours} 접수</span><span>예산·전달 일정 상담</span></div></div>
{illustration ? <figure class="detail-product editorial-hero" data-asset-type={illustration.assetType}><img src={illustration.img} alt={illustration.alt} loading="eager" width="1000" height="1000"/><figcaption>{illustration.caption}</figcaption></figure> : hero ? <div class="detail-product" data-product-family={hero.family} data-product-key={hero.key}><img src={hero.img} alt={hero.name} loading="eager" width="540" height="540"/><strong>{hero.name}</strong><span>{hero.price.toLocaleString()}원 · 상품 기본가격</span><small>{site.brand} 공식 상품 이미지 · 지역·계절에 따라 구성이 달라질 수 있습니다</small>{hero.family==='congrats' && <small>사진 속 리본은 예시입니다. 전하고 싶은 축하 문구를 상담하세요.</small>}</div> : <aside class="detail-product"><h2>목적에 맞는 상품을 상담하세요</h2><p>원하는 형태와 전달 장소를 알려주시면 실제 주문 가능한 상품을 확인할 수 있습니다.</p><a class="btn primary" href={site.phoneHref}>전화 상담</a></aside>}
</section>
{page.pageType==='hospital-visit' && <aside class="caution"><strong>병동 반입 가능 여부부터 확인해 주세요</strong><p>생화 반입은 병원·병동에 따라 제한될 수 있습니다. 병동 확인 전에는 꽃을 주문하지 마시고, 반입이 허용되는 경우에만 아래 상품을 비교해 주세요.</p></aside>}
{page.contentMarkdown ? <MarkdownContent content={page.contentMarkdown} firstAnswer={page.firstAnswer}/> : page.sections.slice(0,3).map((s:any)=><section class="content-card"><h2>{s[0]}</h2><p><InlineText text={s[1]}/></p></section>)}
<InlineOrderBanner/>
{pricePage && pricePage.pageKey!==page.pageKey && <aside class="journey-link"><span>예산을 먼저 정하고 싶다면</span><a href={pricePage.url}>{pricePage.primaryKeyword} 확인 →</a></aside>}
{productSet.length>0 && <section class="product-section compact"><h2>{productHeading(page)}</h2><ProductCards products={productSet}/></section>}
{!page.contentMarkdown && page.sections.slice(3).map((s:any)=><section class="content-card"><h2>{s[0]}</h2><p><InlineText text={s[1]}/></p></section>)}
{addressPage && <aside class="journey-link"><span>상품을 정했다면 수령정보를 준비해 주세요</span><a href={addressPage.url}>{addressPage.primaryKeyword} 확인 →</a></aside>}
{sources.map(source => <section class="source-card" data-source-type={source.type}><h2>{source.name}</h2><p>{sourceTypeLabels[source.type as keyof typeof sourceTypeLabels]}</p><a href={source.url} rel="nofollow" aria-label={`${source.name} 출처 확인`}>출처 확인 →</a><small>확인일 <time datetime={source.verifiedAt}>{source.verifiedAt}</time></small></section>)}
{!page.contentMarkdown && page.faq?.length>0 && <section class="faq"><h2>{page.primaryKeyword} 자주 묻는 질문</h2>{page.faq.map((f:any)=><div><h3>{f[0]}</h3><p>{f[1]}</p></div>)}</section>}
{journey.length>0 && <section class="related" data-journey="next-step"><h2>다음 주문 단계</h2><div class="card-grid journey-grid">{journey.map((p:any)=><a class="page-card" href={p.url}><strong>{p.primaryKeyword}</strong><span>{p.cardSummary}</span></a>)}</div></section>}
{related.length>0 && <section class="related" data-journey="related-reading"><h2>함께 읽을 안내</h2><div class="card-grid journey-grid">{related.map((p:any)=><a class="page-card" href={p.url}><strong>{p.primaryKeyword}</strong><span>{p.cardSummary}</span></a>)}</div></section>}
<section class="conversion-panel"><div><span class="eyebrow">{site.brand} 주문</span><h2>어떤 꽃을 고를지 고민되시면 편하게 문의하세요</h2><p>전화 {site.phone} · {site.phoneOrderHours} / 온라인 {site.onlineOrderHours} 접수</p></div><div class="actions"><a class="btn light" href={site.phoneHref}>전화주문</a><a class="btn yellow" href={hero?.orderUrl || site.orderUrl}>상품 확인·주문</a></div></section>
</article></BaseLayout>

src/pages/[category]/index.astro.utf8Content:
---
import InlineOrderBanner from '../../components/InlineOrderBanner.astro';
import BaseLayout from '../../layouts/BaseLayout.astro';
import pages from '../../data/pages.json';
import products from '../../data/products.json';
import ProductCards from '../../components/ProductCards.astro';
import {site,groups} from '../../config/site';
import {hubGuide,hubProducts} from '../../lib/hubs.mjs';
import editorial from '../../data/editorial-assets.json';
import RegionDirectory from '../../components/RegionDirectory.astro';
export function getStaticPaths(){return groups.map(g=>({params:{category:g.cat},props:{group:g}}));}
const {group}=Astro.props; const items=(pages as any[]).filter(p=>p.category===group.cat);
const isRegional=group.cat==='regions';
const guide=isRegional ? null : hubGuide(group.cat,products,site); const selected=isRegional ? [] : hubProducts(group.cat,products,group.cat==='order'?4:3);
const hero=selected[0];
const illustration=group.cat==='business'?(editorial as {openingWreath:any}).openingWreath:null;
const addressPage=(pages as any[]).find(p=>p.visualIntent==='order_address');
---
<BaseLayout title={`${site.region} ${group.label} 꽃배달 | ${site.brand}`} description={isRegional ? '양주의 공연·전시·개업과 조문에 전할 꽃을 찾아보세요. 사진과 기본가격을 비교하고 마음과 예산에 맞춰 상담하세요.' : guide!.intro} canonicalPath={group.url} noindex={items.length < 3} orderUrl={hero?.orderUrl || site.orderUrl} socialProduct={hero || products[0]}>
<nav class="breadcrumb" aria-label="현재 위치"><a href="/">{site.region} 꽃배달</a><span>›</span><span>{group.label}</span></nav>
{isRegional ? <RegionDirectory pages={items}/> : <>
<section class="category-hero hub-hero"><div><span class="eyebrow">{site.brand} {site.region}</span><h1>{site.region} {group.label} 꽃배달</h1><p>{guide!.intro}</p><ul class="decision-list">{guide!.decision.map((tip:string)=><li>{tip}</li>)}</ul><div class="actions"><a class="btn primary" href={site.phoneHref}>전화 상담·주문</a><a class="btn dark" href={hero?.orderUrl || site.orderUrl}>{guide!.cta}</a></div></div>{illustration ? <figure class="hub-product editorial-hero" data-asset-type={illustration.assetType}><img src={illustration.img} alt={illustration.alt} width="1000" height="1000" loading="eager"/><figcaption>{illustration.caption}</figcaption></figure> : hero && <a class="hub-product" href={hero.orderUrl} data-product-family={hero.family} data-product-key={hero.key}><img src={hero.img} alt={hero.name} width="420" height="420" loading="eager"/><strong>{hero.name} · {hero.price.toLocaleString()}원</strong><span>상품 확인·주문 →</span></a>}</section>
{group.cat==='gift' && <aside class="caution"><strong>병문안은 꽃 반입 가능 여부를 먼저 확인하세요</strong><p>병원·병동에 따라 생화가 제한될 수 있습니다. 수령 가능 여부를 확인한 뒤 꽃다발·꽃바구니를 선택해 주세요.</p></aside>}
<section class="product-section"><h2>{guide!.heading}</h2><ProductCards products={selected}/></section>
