import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import {displayMarkdownBlocks,markdownBlocks} from '../src/lib/content.mjs';

const answer='빈소와 상주 성함을 확인한 뒤 주문해 주세요.';
const rest='\n\n## 주문 정보\n\n[전화 주문](tel:18440644)\n\n- 공식 출처 확인';
test('drops only the identical plain first paragraph and keeps all later blocks',()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+rest,answer),markdownBlocks(rest));
});
test('keeps different text and treats a single time-range tilde as plain text',()=>{
  const different='배송지부터 확인해 주세요.';
  assert.deepEqual(displayMarkdownBlocks(different+rest,answer),markdownBlocks(different+rest));
  const hours='전화주문 08:00~23:00';
  assert.deepEqual(displayMarkdownBlocks(hours+rest,hours),markdownBlocks(rest));
});
test('keeps a later repetition even after dropping the first paragraph',()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+'\n\n'+answer+rest,answer),markdownBlocks(answer+rest));
});
test('compares existing renderer text exactly without whitespace or Unicode normalization',()=>{
  for(const first of [' '+answer,answer+' ',answer.replace('빈소와','빈소와  '),answer.replace('.','!')])
    assert.deepEqual(displayMarkdownBlocks(answer+rest,first),markdownBlocks(answer+rest));
  assert.deepEqual(displayMarkdownBlocks('가'+rest,'가'),markdownBlocks('가'+rest));
});
test('existing multiline paragraph rendering is retained before exact comparison',()=>{
  const text='빈소와 상주 성함을\n확인한 뒤 주문해 주세요.';
  assert.deepEqual(displayMarkdownBlocks(text+rest,answer),markdownBlocks(rest));
});
for(const value of [undefined,null,'','   ',42])test(`no valid first answer: ${String(value)}`,()=>{
  assert.deepEqual(displayMarkdownBlocks(answer+rest,value),markdownBlocks(answer+rest));
});
for(const [label,lead] of Object.entries({
  'link':`[${answer}](https://fwith.co.kr)`,
  'strong':`**${answer}**`,
  'emphasis':`*${answer}*`,
  'underscore':`_${answer}_`,
  'strikethrough':`~~${answer}~~`,
  'inline code':'`'+answer+'`',
  'image':`![${answer}](/image.jpg)`,
  'raw tag':`<p>${answer}</p>`,
  'attributed paragraph':`<p class="intro">${answer}</p>`,
  'inline span':`<span>${answer}</span>`,
  'comment':answer+'<!-- keep -->',
  'leading comment':'<!-- keep -->\n'+answer,
  'heading':'## '+answer,
  'list':'- '+answer,
  'ordered list':'1. '+answer,
  'reference link':'['+answer+'][source]',
  'named entity':'&copy;',
  'numeric entity':'&#128;',
  'escaped ampersand':'&amp;',
  'unknown entity':'&uncertain;',
  'incomplete entity':'&amp',
}))test(`preserves ${label}, even if its raw spelling is the firstAnswer`,()=>{
  for(const firstAnswer of [lead,answer])
    assert.deepEqual(displayMarkdownBlocks(lead+rest,firstAnswer),markdownBlocks(lead+rest));
});
test('eligible frozen pages remove exactly one duplicate and other pages stay intact',()=>{
  const pages=JSON.parse(fs.readFileSync(new URL('../src/data/pages.json',import.meta.url)));
  const before=JSON.stringify(pages);
  for(const page of pages){
    const original=markdownBlocks(page.contentMarkdown);
    const first=original[0];
    const eligible=first?.type==='p' && first.text===page.firstAnswer && !/[<>&*_`\[\]]|~~/.test(first.text);
    assert.deepEqual(displayMarkdownBlocks(page.contentMarkdown,page.firstAnswer),eligible?original.slice(1):original);
  }
  assert.equal(JSON.stringify(pages),before);
});
test('component receives the independently retained hero answer without raw HTML or CSS changes',()=>{
  const detail=fs.readFileSync(new URL('../src/pages/[category]/[slug].astro',import.meta.url),'utf8');
  const component=fs.readFileSync(new URL('../src/components/MarkdownContent.astro',import.meta.url),'utf8');
  assert.match(detail,/<p>\{page.firstAnswer\}<\/p>/);
  assert.match(detail,/<MarkdownContent content=\{page.contentMarkdown\} firstAnswer=\{page.firstAnswer\}\/>/);
  assert.match(component,/displayMarkdownBlocks/);assert.doesNotMatch(component,/set:html|<style/);
});

tests/catalog.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import {productFamilies} from '../src/lib/catalog.mjs';

const family=(pageType,primaryKeyword,visualIntent='consultation',category='order')=>
  productFamilies({pageType,primaryKeyword,visualIntent,category});
test('funeral-only order promises show funeral products',()=>{
  assert.deepEqual(family('message-guide','예시지역 근조화환 리본 문구'),['funeral']);
  assert.deepEqual(family('price-guide','예시지역 근조화환 가격'),['funeral']);
});
test('congratulation-only order promises show congratulations products',()=>{
  assert.deepEqual(family('message-guide','예시지역 축하화환 리본 문구'),['congrats']);
  assert.deepEqual(family('price-guide','예시지역 축하화환 가격'),['congrats']);
});
test('broad wreath comparison can show both, gift and performance exclude wreaths',()=>{
  assert.deepEqual(family('message-guide','예시지역 화환 문구','wreath_message'),['funeral','congrats']);
  assert.deepEqual(family('price-guide','예시지역 근조·축하화환 가격','flower_price'),['funeral','congrats']);
  assert.throws(()=>family('price-guide','예시지역 근조·축하화환 가격','funeral_wreath'),/contradicts/);
  assert.deepEqual(family('hospital-visit','예시지역 병문안 꽃','consultation','gift'),['bouquet','basket']);
  assert.deepEqual(family('event-venue','예시지역 공연 축하꽃','performance_venue','event'),['bouquet']);
});

tests/customer-copy-20261011.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url),'utf8'));
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const pages=read('src/data/pages.json'), proof=read('src/data/customer-copy-review-20261011.json'), history=read('docs/customer-copy-history-20261011.json');
const customer=['title','primaryKeyword','h1','description','cardSummary','firstAnswer','contentMarkdown','sections','faq','sources','source','sourceData'];
test('all20 customer revisions equal independently reviewed exact copy inputs',()=>{
 assert.equal(pages.length,20);assert.equal(proof.approvedCustomerPages.length,20);
 for(const p of pages){const a=proof.approvedCustomerPages.find(a=>a.pageKey===p.pageKey);assert.ok(a);for(const k of customer)assert.deepEqual(p[k],a[k],`${p.slug}:${k}`);}
 for(const [role,item] of Object.entries(proof.approvalBasis))assert.equal(hash(item.utf8Content),item.sha256,role);
});
test('original identities, membership, products and initial denominator remain unchanged',()=>{
 const omit=new Set([...customer,'snapshotId','snapshotHash']);
 const filtered=p=>Object.fromEntries(Object.entries(p).filter(([k])=>!omit.has(k)));
 assert.deepEqual(pages.map(filtered),history.oldData['pages.json'].map(filtered));
 for(const name of ['page-map','architecture','publish-manifest']){
  const current=read(`src/data/${name}.json`), old=history.oldData[`${name}.json`];
  assert.equal(current.pages.length,old.pages.length);
  if(name==='publish-manifest'){
   assert.equal(current.directRelease.plannedOriginalCount,22);
   const d=x=>Object.fromEntries(Object.entries(x).filter(([k])=>k!=='contentHashes'));
   assert.deepEqual(d(current.directRelease),d(old.directRelease));
   assert.equal(current.customerCopyRevision.newArticles,0);
   assert.deepEqual(current.customerCopyRevision.heldRoutes,['/regions/mansong-dong/','/regions/nam-myeon/']);
  }
 }
});
test('catalog descriptions are the only product changes; original business facts and image paths remain',()=>{
 const strip=p=>Object.fromEntries(Object.entries(p).filter(([k])=>k!=='desc'));
 assert.deepEqual(read('src/data/products.json').map(strip),history.oldData['products.json'].map(strip));
 const manifest=JSON.parse(proof.approvalBasis.choiceCommonManifest.utf8Content);
 for(const row of manifest.commonChanges){assert.equal(hash(fs.readFileSync(new URL('../'+row.path,import.meta.url))),row.proposalSha256,row.path);}
});
test('initial evidence stays historical and revised snapshots cannot reuse old content hashes',()=>{
 assert.equal(history.baselineSource,'e1a0ca7a178f1e25d3f6a34855f7f51cf66d822e');
 for(const p of pages){const old=history.oldData['pages.json'].find(x=>x.pageKey===p.pageKey);assert.notEqual(p.snapshotHash,old.snapshotHash);}
 assert.equal(proof.externalWrites,0);
 assert.equal(proof.releaseId,'yangju-customer-copy-20261011');
});

// Exact independently reviewed bytes; independent data pins and pending-state invariants.
const evidencePins={
  "docs/customer-copy-history-20261011.json": "2ef33722832cebf82a2d932c3e8b9ded69a5adcceb8b4205a27dcb6b5f08e35c",
  "src/data/customer-copy-review-20261011.json": "65a305fcd17d342f57a2fb2e0ba6ebccbed342c37ebc1d0fdac7d35082033322",
  "src/data/direct-checkpoint.json": "bee10a304b7b0903a8fe6ed620e8cdf230e19c1042ba1631843cbbd5b8e34109"
};
const finalCommonPins={
  "src/components/InlineOrderBanner.astro": "a73a1e97d36f63923870360a00aa0ac5a8c7cac3fa06ea0694cf2e9acda947c8",
  "src/components/InlineText.astro": "ac748bd0e67c41dab43634bbb63a606d2f2124d1f2c089b1266a52795c3ceb0a",
  "src/components/MarkdownContent.astro": "664e29b01720f12ac6b479b9fe722907c192f1df44338ba3df9a764ba7e3ac77",
  "src/components/ProductCards.astro": "d26eefffb698baceaa06d30a1f40c8d7c576d02f47e76db107f0084dd589605c",
  "src/components/RegionDirectory.astro": "7716824884330df48ba1a94f5beab91c9aaf6d427ad61e9c8ec36f1d0382e915",
  "src/data/business-truth.json": "3e1be4b64f26d88bc874a72ce8e0597ba092bd22e4e0c7d205314acb23349ee0",
  "src/data/products.json": "9f9470505da88ec2aab9ca86290014024e79c5730a7d4e82ce9478a6164b9e6d",
  "src/layouts/BaseLayout.astro": "cb0eadcc8d98bb3a61256d4efba40fb5c16370e5d0ba6189ed63531f9a437fa1",
  "src/lib/sources.mjs": "411ce236880502a2cbe25270ee76101211b3ce11223fb3225c3473da8baae5be",
  "src/pages/404.astro": "f4497cf673dd7cf0e2d045ec7c8253fb56f20b366689efea473e36c080adae9e",
  "src/pages/[category]/[slug].astro": "7d7396db8a3a722778ee90a254a1780383990b671c94e470bd326d04229823b2",
  "src/pages/[category]/index.astro": "b564eefedb0186b4e9a5ba481ebee7216f840d12b6f20a6a9f2d3e2f05ec6c7f",
  "src/pages/index.astro": "716bd2a6306532e7bd6770a871e8c1e6fb7542a8619e96c8703416c45d55f123"
};
const allowedCopyCheckpoint={
  "releaseId": "yangju-customer-copy-20261011",
  "baselineSource": "e1a0ca7a178f1e25d3f6a34855f7f51cf66d822e",
  "originalPlanN": 22,
  "existingArticles": 20,
  "newArticles": 0,
  "heldRoutes": [
    "/regions/mansong-dong/",
    "/regions/nam-myeon/"
  ],
  "initialHistory": "docs/customer-copy-history-20261011.json",
  "copyReview": "src/data/customer-copy-review-20261011.json",
  "state": "local-integrated-source-pending-independent-code-review"
};
const bytes=p=>fs.readFileSync(new URL('../'+p,import.meta.url));
const validatePinned=(values,pins)=>{for(const [p,expected] of Object.entries(pins))assert.equal(hash(values[p]),expected,p);};
const validateCheckpoint=x=>assert.deepEqual(x,allowedCopyCheckpoint,'copy checkpoint must retain exact pending state and allowed fields');
test('proof, original history and initial checkpoint are pinned to independently reviewed bytes',()=>{
 validatePinned(Object.fromEntries(Object.keys(evidencePins).map(p=>[p,bytes(p)])),evidencePins);
});
test('all final customer common surfaces remain bound to reviewed bytes',()=>{
 validatePinned(Object.fromEntries(Object.keys(finalCommonPins).map(p=>[p,bytes(p)])),finalCommonPins);
});
test('local copy state cannot become false hosted or visual completion',()=>{
 validateCheckpoint(read('src/data/publish-manifest.json').customerCopyRevision);
});
test('negative evidence, common copy and false completion fixtures fail closed',()=>{
 const e=Object.fromEntries(Object.keys(evidencePins).map(p=>[p,bytes(p)]));
 for(const path of Object.keys(evidencePins)){const changed={...e,[path]:Buffer.concat([e[path],Buffer.from(' ')] )};assert.throws(()=>validatePinned(changed,evidencePins));}
 const c=Object.fromEntries(Object.keys(finalCommonPins).map(p=>[p,bytes(p)]));
 for(const path of Object.keys(finalCommonPins)){const changed={...c,[path]:Buffer.concat([c[path],Buffer.from('<!-- changed -->')])};assert.throws(()=>validatePinned(changed,finalCommonPins));}
 for(const fields of [{state:'published',publicComplete:true},{visualQa:'PASS'},{indexnow:'received'},{integrationReview:'PASS'}])assert.throws(()=>validateCheckpoint({...allowedCopyCheckpoint,...fields}));
});

tests/direct-source.test.mjs.utf8Content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {selectProducts} from '../src/lib/catalog.mjs';
const read=name=>JSON.parse(fs.readFileSync(new URL(`../src/data/${name}.json`,import.meta.url),'utf8'));
const sha=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a<b?-1:a>b?1:0)):x);
const slugs=["yuyang-dong", "eodun-dong", "nambang-dong", "majeon-dong", "sanbuk-dong", "gwangsa-dong", "mansong-dong", "samsung-dong", "goeup-dong", "deokjeong-dong", "bongyang-dong", "hoeam-dong", "yuljeong-dong", "okjeong-dong", "goam-dong", "deokgye-dong", "hoejeong-dong", "baekseok-eup", "eunhyeon-myeon", "nam-myeon", "gwangjeok-myeon", "jangheung-myeon"];
test('Yangju frozen official legal and administrative membership has no duplicate canonical aliases',()=>{
 const pages=read('pages'),coverage=read('region-coverage');
 assert.deepEqual(pages.map(p=>p.slug),["yuyang-dong", "eodun-dong", "nambang-dong", "majeon-dong", "sanbuk-dong", "gwangsa-dong", "samsung-dong", "goeup-dong", "deokjeong-dong", "bongyang-dong", "hoeam-dong", "yuljeong-dong", "okjeong-dong", "goam-dong", "deokgye-dong", "hoejeong-dong", "baekseok-eup", "eunhyeon-myeon", "gwangjeok-myeon", "jangheung-myeon"]);assert.equal(coverage.units.length,22);assert.equal(coverage.administrativeCrosswalk.length,12);
 assert.equal(new Set(coverage.administrativeCrosswalk.map(a=>a.aliasKey)).size,12);
 assert.equal(coverage.districts.length,1);assert.equal(coverage.districts[0].name,'양주시');assert.equal(coverage.representatives.length,20);
 for(const p of pages){assert.equal(p.category,'regions');assert.equal(p.pageType,'regional-service');assert.equal(p.url,`/regions/${p.slug}/`);}
 const names=alias=>coverage.administrativeCrosswalk.find(a=>a.name===alias).relations.map(r=>coverage.units.find(u=>u.unitKey===r.unitKey).name).sort();
 for(const [admin,legal] of Object.entries({"광적면": ["광적면"], "남면": ["남면"], "백석읍": ["백석읍"], "양주1동": ["남방동", "마전동", "산북동", "어둔동", "유양동"], "양주2동": ["고읍동", "광사동", "만송동", "삼숭동"], "옥정1동": ["옥정동", "율정동", "회암동"], "옥정2동": ["옥정동"], "은현면": ["은현면"], "장흥면": ["장흥면"], "회천1동": ["덕정동", "봉양동"], "회천2동": ["덕계동", "회정동"], "회천3동": ["고암동", "덕정동"]}))assert.deepEqual(names(admin),legal);
 const actualRelations=coverage.administrativeCrosswalk.flatMap(a=>a.relations.map(r=>({administrativeDong:a.name,name:coverage.units.find(u=>u.unitKey===r.unitKey).name,coverage:r.scope}))); const relationKey=r=>`${r.administrativeDong}|${r.name}`; const sortRelations=values=>values.sort((a,b)=>relationKey(a)<relationKey(b)?-1:relationKey(a)>relationKey(b)?1:0); assert.deepEqual(sortRelations(actualRelations),sortRelations([{"administrativeDong": "광적면", "name": "광적면", "coverage": "whole"}, {"administrativeDong": "남면", "name": "남면", "coverage": "whole"}, {"administrativeDong": "백석읍", "name": "백석읍", "coverage": "whole"}, {"administrativeDong": "양주1동", "name": "남방동", "coverage": "whole"}, {"administrativeDong": "양주1동", "name": "마전동", "coverage": "whole"}, {"administrativeDong": "양주1동", "name": "산북동", "coverage": "whole"}, {"administrativeDong": "양주1동", "name": "어둔동", "coverage": "whole"}, {"administrativeDong": "양주1동", "name": "유양동", "coverage": "whole"}, {"administrativeDong": "양주2동", "name": "고읍동", "coverage": "whole"}, {"administrativeDong": "양주2동", "name": "광사동", "coverage": "whole"}, {"administrativeDong": "양주2동", "name": "만송동", "coverage": "whole"}, {"administrativeDong": "양주2동", "name": "삼숭동", "coverage": "whole"}, {"administrativeDong": "옥정1동", "name": "옥정동", "coverage": "partial"}, {"administrativeDong": "옥정1동", "name": "율정동", "coverage": "whole"}, {"administrativeDong": "옥정1동", "name": "회암동", "coverage": "whole"}, {"administrativeDong": "옥정2동", "name": "옥정동", "coverage": "partial"}, {"administrativeDong": "은현면", "name": "은현면", "coverage": "whole"}, {"administrativeDong": "장흥면", "name": "장흥면", "coverage": "whole"}, {"administrativeDong": "회천1동", "name": "덕정동", "coverage": "partial"}, {"administrativeDong": "회천1동", "name": "봉양동", "coverage": "whole"}, {"administrativeDong": "회천2동", "name": "덕계동", "coverage": "whole"}, {"administrativeDong": "회천2동", "name": "회정동", "coverage": "whole"}, {"administrativeDong": "회천3동", "name": "고암동", "coverage": "whole"}, {"administrativeDong": "회천3동", "name": "덕정동", "coverage": "partial"}])); assert.equal(actualRelations.filter(r=>r.coverage==='partial').length,4);
 assert.ok(coverage.units.every(u=>u.unitKey===`양주시/${({'legal-dong':'법정동','eup':'읍','myeon':'면'})[u.unitType]}/${u.name}`));
 assert.deepEqual(Object.fromEntries(['legal-dong','eup','myeon'].map(type=>[type,coverage.units.filter(u=>u.unitType===type).length])),{'legal-dong':17,eup:1,myeon:4});
 assert.equal(coverage.administrativeCrosswalk.flatMap(a=>a.relations).length,24);
 assert.equal(coverage.units.length,slugs.length);
 assert.ok(pages.length*10>=slugs.length*9);
});
test('direct snapshot hashes bind every public customer field and all four page collections',()=>{
 const pages=read('pages'),manifest=read('publish-manifest');
 assert.equal(manifest.directRelease.sourceMode,'direct-git');assert.deepEqual(manifest.snapshotLedger,{});
 assert.equal(manifest.directRelease.plannedOriginalCount,22);assert.equal(manifest.directRelease.reviewedArticleCount,20);
 for(const p of pages){
  const omit=new Set(['approvalVerified','status','file','order','sourceMode','snapshotId','snapshotHash']);
  const digest=sha(canonical(Object.fromEntries(Object.entries(p).filter(([k])=>!omit.has(k)))));
  assert.equal(p.snapshotHash,digest);assert.equal(p.snapshotId,`direct-content-${p.slug}-${digest.slice(0,16)}`);
  const row=manifest.directRelease.contentHashes.find(x=>x.pageKey===p.pageKey);
  assert.equal(row.publicSourceSha256,digest);assert.equal(row.bodySha256,sha(p.contentMarkdown));
  for(const c of [manifest,read('page-map'),read('architecture')])assert.equal(c.pages.find(x=>x.pageKey===p.pageKey).snapshotHash,digest);
 }
});
